import {armTurn,turnExpired} from './turn-clock.mjs';
import {timeoutMonth} from './turn-timeout.mjs';
import {createGame,prepareMove,chooseMove,resolve,manage,score,netWorth} from './engine.mjs';
import {createHub,beginRun,settleRun,abandonRun,unlocked} from './hub.mjs';
import {questionPool} from './events.mjs';
import {matchStake,competitionPlan} from './competition.mjs';
const player=i=>({name:'Player '+(i+1),hub:createHub(),game:null});
export function createDuel(count=2){if(!Number.isInteger(count)||count<2||count>6)throw Error('2–6 players');return {version:1,seed:1,level:'easy',round:0,turn:0,active:false,done:false,handoff:false,memory:{},players:Array.from({length:count},(_,i)=>player(i)),bench:[],treasury:{balance:0,carry:0,history:[]}};}
export function resizeDuel(d,count){if(d.active||d.done||!Number.isInteger(count)||count<2||count>6)return false;const roster=[...d.players,...(d.bench||[])];while(roster.length<count)roster.push(player(roster.length));d.players=roster.slice(0,count);d.bench=roster.slice(count);return true;}
const mix=n=>{n=(n^(n>>>16))>>>0;n=Math.imul(n,0x7feb352d);n=(n^(n>>>15))>>>0;n=Math.imul(n,0x846ca68b);return (n^(n>>>16))>>>0;};
export const duelSchedule=(seed,month)=>({die:1+mix(seed+month*31)%6,offset:1+mix(seed+month*53+29)%5,eventSeed:mix(seed+month*101+17)});
export function startDuel(d,level,seed){if(d.active||!d.players.every(p=>unlocked(p.hub,level)&&p.hub.balance>=matchStake(level)))return false;const copy=structuredClone(d);copy.seed=seed>>>0;copy.level=level;copy.round++;copy.turn=0;copy.done=false;copy.handoff=true;copy.betRules=1;copy.betResult=null;copy.lastFeedback=null;copy.treasury??={balance:0,carry:0,history:[]};for(let i=0;i<copy.players.length;i++){const p=copy.players[i],g=createGame(level);if(!beginRun(p.hub,g,`duet-${copy.seed}-${copy.round}-${i}`,'challenge',true))return false;p.stake=matchStake(level);p.hub.balance-=p.stake;p.hub.ledger.unshift({kind:'bet-lock',amount:-p.stake,level,round:copy.round});const memory=copy.memory[level]||[];g.usedQuestions=questionPool(g).some(q=>!memory.includes(q.id))?[...memory]:[];p.game=g;p.receipt=null;}for(const p of copy.players)delete p.game.turnDeadline;armTurn(copy.players[0].game);copy.active=true;Object.assign(d,copy);return true;}
export function settleCompetition(d){if(!d.betRules||d.betResult||!d.players.every(p=>p.game?.phase==='finished'))return false;
 const result=competitionPlan(d.players,matchStake(d.level),d.treasury.carry);for(const r of result.rows){const p=d.players[r.index];p.hub.balance+=r.refund+r.betReward;p.hub.betEarned=(p.hub.betEarned||0)+r.betReward;p.hub.betLost=(p.hub.betLost||0)+r.betLoss;p.hub.ledger.unshift({kind:'bet-settle',amount:r.refund+r.betReward,refund:r.refund,reward:r.betReward,loss:r.betLoss,level:d.level,round:d.round});p.hub.ledger=p.hub.ledger.slice(0,50);p.stake=0;}d.treasury.balance+=result.treasury;d.treasury.carry=result.carryOut;d.treasury.history.unshift({round:d.round,level:d.level,players:d.players.length,contribution:result.treasury,carryIn:result.carryIn,carryOut:result.carryOut,payout:result.rows.reduce((n,r)=>n+r.betReward,0)});d.treasury.history=d.treasury.history.slice(0,50);d.betResult=result;return true;}
function next(d,now=Date.now()){delete d.players[d.turn].game.turnDeadline;const p=d.players[d.turn];if(p.game.phase==='finished'){settleRun(p.hub,p.game);d.memory[d.level]=[...new Set([...(d.memory[d.level]||[]),...p.game.usedQuestions])];}if(d.players.every(p=>p.game.phase==='finished')){settleCompetition(d);d.done=true;d.active=false;d.handoff=false;return;}for(let k=1;k<=d.players.length;k++){const index=(d.turn+k)%d.players.length;if(d.players[index].game.phase!=='finished'){d.handoff=index!==d.turn;d.turn=index;armTurn(d.players[index].game,now);return;}}}
export function duelAct(d,action,now=Date.now()){if(!d.active||d.handoff)return false;const s=d.players[d.turn].game;if(action==='roll'){const plan=duelSchedule(d.seed,s.month+1);return prepareMove(s,plan.die,plan.offset,plan.eventSeed,now);}if(action.startsWith('route-')){if(!chooseMove(s,Number(action.slice(6))))return false;if(s.phase==='finished')next(d);return true;}if(action.startsWith('manage-'))return manage(s,action.slice(7));if(!resolve(s,action))return false;next(d);return true;}
export function abandonDuel(d){if(!d.active)return false;if(!d.betRules){for(const p of d.players)abandonRun(p.hub,p.game);d.active=false;d.done=false;d.handoff=false;return true;}
 // Leaving the shared match forfeits every unfinished seat. Completed Hub clears retain their eligibility and rewards.
 for(const p of d.players){if(p.game.phase==='finished')continue;p.game.competitionAbandoned=true;abandonRun(p.hub,p.game);p.game.phase='finished';p.game.labResult={won:false,reward:0,loss:0};}settleCompetition(d);d.active=false;d.done=true;d.handoff=false;return true;}
export function duelRanking(d){if(!d.done)return null;if(d.betResult){return d.betResult.winners.length===1?d.betResult.winners[0]:-1;}const metrics=d.players.map(p=>[Number(p.game.month===12&&p.game.shortfall===0),p.game.month,score(p.game).total,netWorth(p.game),p.game.reserve]);for(let i=0;i<5;i++)if(metrics[0][i]!==metrics[1][i])return metrics[0][i]>metrics[1][i]?0:1;return -1;}

export function resignDuel(d){if(!d.active)return false;const p=d.players[d.turn],s=p.game;if(s.phase==='finished')return false;abandonRun(p.hub,s);s.competitionAbandoned=true;s.phase='finished';s.pending=null;delete s.route;s.month=s.history.length;s.labResult={won:false,reward:0,loss:0};next(d);return true;}

export function timeoutDuel(d,now=Date.now()){if(!d.active)return 0;let count=0;const current=d.players[d.turn].game;if(!current.route&&current.phase!=='event'){if(Number.isFinite(current.turnDeadline)){delete current.turnDeadline;return -1;}return 0;}if(!Number.isFinite(current.turnDeadline)){armTurn(current,now);return -1;}while(d.active&&turnExpired(d.players[d.turn].game,now)&&count<72){const s=d.players[d.turn].game,deadline=s.turnDeadline;if(!timeoutMonth(s,duelSchedule(d.seed,s.month+1)))break;next(d,deadline);d.handoff=false;count++;}return count;}
